<?php
$line = trim(fgets(STDIN));
list($a, $b, $c) = array_map('intval', explode(' ', $line));

// Try to find x (between a and b), y (between b and c), z (between c and a)
// such that:
//   x + z = a
//   x + y = b
//   y + z = c
// Solving:
//   x = (a + b - c) / 2
//   y = (b + c - a) / 2
//   z = (a + c - b) / 2
// All must be non-negative integers.

$sum = $a + $b + $c;
if ($sum % 2 !== 0) {
    echo "Impossible";
    exit;
}

$x = ($a + $b - $c) / 2;
$y = ($b + $c - $a) / 2;
$z = ($a + $c - $b) / 2;

if ($x >= 0 && $y >= 0 && $z >= 0 &&
    ($x + $z) === $a &&
    ($x + $y) === $b &&
    ($y + $z) === $c) {
    echo "$x $y $z";
} else {
    echo "Impossible";
}
?>
